using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3–100 characters.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Description is required.")]
    [StringLength(500, MinimumLength = 10, ErrorMessage = "Description must be 10–500 characters.")]
    public string Description { get; set; } = "";

    [Required(ErrorMessage = "Ingredients are required.")]
    [MinLength(1, ErrorMessage = "Add at least one ingredient.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Steps are required.")]
    [MinLength(1, ErrorMessage = "Add at least one step.")]
    public string Steps { get; set; } = "";
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = GetSeedRecipes();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<RecipeCategory> GetCategories()
    {
        return
        [
            new() { Name = "Breakfast", Description = "Start your day right with hearty morning meals", Icon = "🥞", RecipeCount = _recipes.Count(r => r.Category == "Breakfast") },
            new() { Name = "Lunch", Description = "Quick and satisfying midday dishes", Icon = "🥗", RecipeCount = _recipes.Count(r => r.Category == "Lunch") },
            new() { Name = "Dinner", Description = "Delicious evening meals for the whole family", Icon = "🍝", RecipeCount = _recipes.Count(r => r.Category == "Dinner") },
            new() { Name = "Desserts", Description = "Sweet treats and indulgent finishes", Icon = "🍰", RecipeCount = _recipes.Count(r => r.Category == "Desserts") },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🍿", RecipeCount = _recipes.Count(r => r.Category == "Snacks") },
            new() { Name = "Drinks", Description = "Refreshing beverages and cocktails", Icon = "🥤", RecipeCount = _recipes.Count(r => r.Category == "Drinks") },
        ];
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
