@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

@if (recipes is null || recipes.Count == 0)
{
    <h1>No recipes found</h1>
    <p>There are no recipes in the "@CategoryName" category yet.</p>
    <a href="submit" class="btn btn-success">Be the first to submit one!</a>
}
else
{
    <h1>@CategoryName Recipes</h1>
    <p class="text-muted mb-4">@recipes.Count recipe(s) in this category</p>

    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <a href="@($"recipe/{recipe.Id}")" class="text-decoration-none">
                    <div class="card h-100 shadow-sm recipe-card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                </span>
                                <small class="text-muted">@recipe.TotalRatings ratings</small>
                            </div>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>
}

<div class="mt-4">
    <a href="/" class="btn btn-outline-secondary">← Back to Categories</a>
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = "";

    private IReadOnlyList<Models.Recipe>? recipes;

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <PageTitle>@recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="@($"category/{recipe.Category.ToLowerInvariant()}")">@recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" TotalRatings="recipe.TotalRatings" />

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card mb-4">
                <div class="card-header">
                    <h4 class="mb-0">🧾 Ingredients</h4>
                </div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-7">
            <div class="card mb-4">
                <div class="card-header">
                    <h4 class="mb-0">📋 Instructions</h4>
                </div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <a href="@($"category/{recipe.Category.ToLowerInvariant()}")" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@rendermode InteractiveServer

@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="my-3">
    <div class="d-flex align-items-center gap-3">
        <div class="star-rating" role="group" aria-label="Rate this recipe">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span class="star @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "filled" : "")"
                      role="button"
                      tabindex="0"
                      aria-label="@star stars"
                      @onclick="() => SubmitRating(star)"
                      @onmouseover="() => hoverRating = star"
                      @onmouseout="() => hoverRating = 0">
                    @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "★" : "☆")
                </span>
            }
        </div>
        <span class="text-muted">
            @if (hasRated)
            {
                <span class="text-success">✓ You rated @selectedRating star(s)!</span>
            }
            else
            {
                <span>@TotalRatings ratings · @CurrentAverage.ToString("0.0") avg</span>
            }
        </span>
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int hoverRating;
    private int selectedRating;
    private bool hasRated;

    private void SubmitRating(int stars)
    {
        if (hasRated) return;

        selectedRating = stars;
        hasRated = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer

@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted mb-4">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Recipe submitted!</h4>
        <p>Your recipe "<strong>@model.Title</strong>" has been added.</p>
        <a href="@($"recipe/{submittedRecipeId}")" class="btn btn-primary">View Recipe</a>
        <a href="submit" class="btn btn-outline-secondary ms-2" @onclick="ResetForm" @onclick:preventDefault>Submit Another</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" class="text-danger" />
