toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer

@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted mb-4">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Recipe submitted!</h4>
        <p>Your recipe "<strong>@model.Title</strong>" has been added.</p>
        <a href="@($"recipe/{submittedRecipeId}")" class="btn btn-primary">View Recipe</a>
        <a href="submit" class="btn btn-outline-secondary ms-2" @onclick="ResetForm" @onclick:preventDefault>Submit Another</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                <option value="Breakfast">Breakfast</option>
                <option value="Lunch">Lunch</option>
                <option value="Dinner">Dinner</option>
                <option value="Desserts">Desserts</option>
                <option value="Snacks">Snacks</option>
                <option value="Drinks">Drinks</option>
            </InputSelect>
            <ValidationMessage For="() => model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Description</label>
            <InputTextArea id="description" class="form-control" rows="2" @bind-Value="model.Description" placeholder="A short description of your recipe" />
            <ValidationMessage For="() => model.Description" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients <small class="text-muted">(one per line)</small></label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps <small class="text-muted">(one per line)</small></label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="model.Steps" placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        <a href="/" class="btn btn-outline-secondary btn-lg ms-2">Cancel</a>
    </EditForm>
}

@code {
    private RecipeSubmission model = new();
    private bool submitted;
    private int submittedRecipeId;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(model);
        submittedRecipeId = recipe.Id;
        submitted = true;
    }

    private void ResetForm()
    {
        model = new RecipeSubmission();
        submitted = false;
    }
}

